source='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            cells = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            boxes = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in boxes:
                    boxes[color] = [y, y, x, x]
                else:
                    b = boxes[color]
                    b[0] = min(b[0], y)
                    b[1] = max(b[1], y)
                    b[2] = min(b[2], x)
                    b[3] = max(b[3], x)
            colors = sorted(boxes, key=lambda color: (-(boxes[color][1] - boxes[color][0] + 1) * (boxes[color][3] - boxes[color][2] + 1), color))
            replacement = dict(zip(colors, reversed(colors)))
            for y, x in cells:
                out[y][x] = replacement[grid[y][x]]
    return out
'''
